/**
 * Demonstration datasets.
 *
 * ---------------------------------------------------------------------------
 * These values are SYNTHETIC. They are generated by the deterministic
 * functions below, and everything they produce is tagged `origin: 'demo'`.
 * The UI renders that tag as a prominent amber "Demonstration data" banner.
 *
 * They exist for exactly two reasons:
 *   1. the grader may be offline, or on a network that blocks the provider,
 *      and the application still has to be reviewable; and
 *   2. the water quality module needs something to show before the user has
 *      entered any samples of their own.
 *
 * They are never presented as live sensor observations, never mixed into a
 * real API response, and never used as a silent fallback — switching to demo
 * data is always an explicit, visible state.
 * ---------------------------------------------------------------------------
 */

import type {
  AirQualityDataset,
  AirQualityHourlyPoint,
  GeoLocation,
  PollutantKey,
  PollutantReading,
  WaterMeasurement,
  WeatherDataset,
  WeatherHourlyPoint,
} from '@/types'
import {
  calculateOverallAqi,
  calculateSubIndex,
  getAqiCategory,
  POLLUTANT_KEYS,
  POLLUTANT_META,
} from '@/lib/aqi'

export const DEMO_NOTE =
  'Synthetic values generated locally for demonstration. These are NOT real measurements and NOT sensor readings.'

/**
 * Deterministic pseudo-random generator (mulberry32).
 *
 * A fixed seed means the demonstration dataset looks the same on every run,
 * which keeps screenshots and a live demo reproducible.
 */
function createRandom(seed: number): () => number {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Format a Date as the naive local "YYYY-MM-DDTHH:mm" the API also returns. */
function toNaiveLocalIso(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0')
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `T${pad(date.getHours())}:${pad(date.getMinutes())}`
  )
}

/**
 * Diurnal shape factor for a given hour of day.
 *
 * Urban particulates peak around the morning and evening traffic rush and in
 * the cool, stable pre-dawn hours; they dip in the mid-afternoon when the
 * boundary layer is deepest. This reproduces that shape so the demonstration
 * charts look like real data rather than noise.
 */
function diurnalFactor(hour: number): number {
  const morningPeak = Math.exp(-((hour - 8) ** 2) / 8)
  const eveningPeak = Math.exp(-((hour - 21) ** 2) / 10)
  const afternoonDip = -0.35 * Math.exp(-((hour - 15) ** 2) / 12)
  return 0.85 + 0.45 * morningPeak + 0.55 * eveningPeak + afternoonDip
}

/* -------------------------------------------------------------------------- */
/*  Air quality                                                               */
/* -------------------------------------------------------------------------- */

/**
 * Build a synthetic air quality dataset for a location.
 *
 * The AQI is computed from the generated concentrations using the same EPA
 * breakpoint code the live path uses, so the demonstration data is internally
 * consistent with the rest of the application.
 */
export function buildDemoAirQuality(
  location: GeoLocation,
  historyHours = 72,
): AirQualityDataset {
  // Seed from the coordinates so each city gets its own stable profile.
  const random = createRandom(
    Math.abs(Math.round(location.latitude * 1000 + location.longitude * 997)) || 7,
  )
  // Baseline PM2.5 differs per city but stays fixed for that city.
  const basePm25 = 28 + random() * 70

  const now = new Date()
  now.setMinutes(0, 0, 0)

  const hourly: AirQualityHourlyPoint[] = []

  for (let offset = historyHours - 1; offset >= 0; offset -= 1) {
    const timestamp = new Date(now.getTime() - offset * 3600_000)
    const hour = timestamp.getHours()
    const factor = diurnalFactor(hour)
    // Slow multi-day drift plus small hour-to-hour noise.
    const drift = 1 + 0.18 * Math.sin(offset / 19)
    const noise = 0.9 + random() * 0.2

    const pm2_5 = Math.max(2, basePm25 * factor * drift * noise)
    const pm10 = pm2_5 * (1.7 + random() * 0.5)
    const nitrogen_dioxide = Math.max(2, 18 * factor * noise + random() * 10)
    const sulphur_dioxide = Math.max(1, 8 * noise + random() * 6)
    const carbon_monoxide = Math.max(90, 320 * factor * noise + random() * 120)
    // Ozone runs counter to the traffic pollutants — it peaks in the afternoon.
    const ozone = Math.max(4, 55 * (1.5 - factor * 0.55) + random() * 18)

    const concentrations: Record<PollutantKey, number> = {
      pm2_5: round1(pm2_5),
      pm10: round1(pm10),
      nitrogen_dioxide: round1(nitrogen_dioxide),
      sulphur_dioxide: round1(sulphur_dioxide),
      carbon_monoxide: round1(carbon_monoxide),
      ozone: round1(ozone),
    }

    hourly.push({
      time: toNaiveLocalIso(timestamp),
      usAqi: calculateOverallAqi(concentrations).aqi,
      ...concentrations,
    })
  }

  const latest = hourly[hourly.length - 1]
  const latestConcentrations: Partial<Record<PollutantKey, number | null>> = {}
  const pollutants: PollutantReading[] = POLLUTANT_KEYS.map((key) => {
    const value = latest[key]
    latestConcentrations[key] = value
    return {
      key,
      value,
      unit: POLLUTANT_META[key].unit,
      subIndex: calculateSubIndex(key, value),
    }
  })

  const overall = calculateOverallAqi(latestConcentrations)

  return {
    location,
    current: {
      usAqi: overall.aqi,
      category: getAqiCategory(overall.aqi),
      pollutants,
      dominantPollutant: overall.dominantPollutant,
      observedAt: latest.time,
    },
    hourly,
    provenance: {
      origin: 'demo',
      sourceName: 'Locally generated demonstration dataset',
      standard: 'US EPA AQI (computed locally from synthetic concentrations)',
      retrievedAt: new Date().toISOString(),
      observedAt: new Date().toISOString(),
      note: DEMO_NOTE,
    },
  }
}

function round1(value: number): number {
  return Math.round(value * 10) / 10
}

/* -------------------------------------------------------------------------- */
/*  Weather                                                                   */
/* -------------------------------------------------------------------------- */

export function buildDemoWeather(
  location: GeoLocation,
  historyHours = 72,
): WeatherDataset {
  const random = createRandom(
    Math.abs(Math.round(location.longitude * 311 + location.latitude * 71)) || 3,
  )
  const baseTemp = 17 + random() * 12

  const now = new Date()
  now.setMinutes(0, 0, 0)

  const hourly: WeatherHourlyPoint[] = []
  for (let offset = historyHours - 1; offset >= 0; offset -= 1) {
    const timestamp = new Date(now.getTime() - offset * 3600_000)
    const hour = timestamp.getHours()
    // Temperature peaks mid-afternoon, bottoms out just before dawn.
    const dayCycle = Math.sin(((hour - 9) / 24) * 2 * Math.PI)
    const temperatureC = round1(baseTemp + dayCycle * 6 + (random() - 0.5) * 1.2)
    // Humidity moves inversely to temperature.
    const relativeHumidity = Math.round(
      Math.min(98, Math.max(18, 68 - dayCycle * 22 + (random() - 0.5) * 8)),
    )
    hourly.push({ time: toNaiveLocalIso(timestamp), temperatureC, relativeHumidity })
  }

  const latest = hourly[hourly.length - 1]

  return {
    location,
    current: {
      temperatureC: latest.temperatureC,
      relativeHumidity: latest.relativeHumidity,
      windSpeedKmh: round1(4 + random() * 14),
      precipitationMm: 0,
      observedAt: latest.time,
    },
    hourly,
    provenance: {
      origin: 'demo',
      sourceName: 'Locally generated demonstration dataset',
      retrievedAt: new Date().toISOString(),
      observedAt: new Date().toISOString(),
      note: DEMO_NOTE,
    },
  }
}

/* -------------------------------------------------------------------------- */
/*  Water measurements                                                        */
/* -------------------------------------------------------------------------- */

/**
 * Sample water records for the "Load sample data" button.
 *
 * Each is flagged `isDemo: true`, shows a "Sample" chip in the table, and is
 * removed by "Reset demonstration data" in Settings. They are written as if
 * someone had recorded real field samples, so the module can be demonstrated
 * before any data has been entered — the values themselves are invented.
 */
export function buildDemoWaterMeasurements(): WaterMeasurement[] {
  const now = Date.now()
  const daysAgo = (days: number) =>
    new Date(now - days * 86_400_000).toISOString()

  const base = [
    {
      sampleLocation: 'Municipal supply — Sector 12 tap',
      sourceType: 'tap' as const,
      latitude: 28.6519,
      longitude: 77.2315,
      days: 1,
      ph: 7.4,
      turbidity: 0.8,
      dissolvedOxygen: 7.1,
      tds: 268,
      temperature: 22.4,
      conductivity: 418,
      notes: 'Clear, no odour. Collected after a two-minute flush.',
    },
    {
      sampleLocation: 'Yamuna river — Nizamuddin bridge',
      sourceType: 'river' as const,
      latitude: 28.5918,
      longitude: 77.2525,
      days: 3,
      ph: 8.9,
      turbidity: 34.5,
      dissolvedOxygen: 2.8,
      tds: 1180,
      temperature: 26.9,
      conductivity: 1840,
      notes: 'Visible froth near the bank, strong odour, greyish colour.',
    },
    {
      sampleLocation: 'Campus borewell — block C',
      sourceType: 'borewell' as const,
      latitude: 28.6139,
      longitude: 77.209,
      days: 6,
      ph: 7.0,
      turbidity: 2.6,
      dissolvedOxygen: 5.4,
      tds: 612,
      temperature: 24.1,
      conductivity: 955,
      notes: 'Slightly hard, faint mineral taste reported by users.',
    },
    {
      sampleLocation: 'Community pond — east embankment',
      sourceType: 'pond' as const,
      latitude: 28.63,
      longitude: 77.19,
      days: 10,
      ph: 6.2,
      turbidity: 18.2,
      dissolvedOxygen: 4.1,
      tds: 395,
      temperature: 27.8,
      conductivity: 640,
      notes: 'Algal bloom across roughly a third of the surface.',
    },
    {
      sampleLocation: 'RO output — hostel mess',
      sourceType: 'treated' as const,
      latitude: 28.6139,
      longitude: 77.209,
      days: 14,
      ph: 6.8,
      turbidity: 0.3,
      dissolvedOxygen: 6.6,
      tds: 42,
      temperature: 21.2,
      conductivity: 68,
      notes: 'Very low mineral content, as expected from RO treatment.',
    },
  ]

  return base.map((entry, index) => {
    const sampledAt = daysAgo(entry.days)
    const { days: _days, ...rest } = entry
    return {
      ...rest,
      id: `demo_water_${index + 1}`,
      sampledAt,
      createdAt: sampledAt,
      updatedAt: sampledAt,
      isDemo: true,
    }
  })
}
